import json
import os
import time
import uuid
from typing import Any, Dict, Iterable, List, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


class CloudWatchCorrelationLogger:
    """
    Writes application log events to Amazon CloudWatch Logs with a shared request/correlation identifier.
    """

    def __init__(
        self,
        log_group_name: str,
        log_stream_name: Optional[str] = None,
        region_name: Optional[str] = None,
    ) -> None:
        self.log_group_name = log_group_name
        self.log_stream_name = log_stream_name or f"app-{os.getpid()}"
        self.region_name = region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION")
        self.client = boto3.client("logs", region_name=self.region_name)

        self._ensure_log_group()
        self._ensure_log_stream()
        self.sequence_token = self._get_sequence_token()

    def _ensure_log_group(self) -> None:
        try:
            self.client.create_log_group(logGroupName=self.log_group_name)
        except ClientError as e:
            code = e.response.get("Error", {}).get("Code", "")
            if code != "ResourceAlreadyExistsException":
                raise

    def _ensure_log_stream(self) -> None:
        try:
            self.client.create_log_stream(
                logGroupName=self.log_group_name,
                logStreamName=self.log_stream_name,
            )
        except ClientError as e:
            code = e.response.get("Error", {}).get("Code", "")
            if code != "ResourceAlreadyExistsException":
                raise

    def _get_sequence_token(self) -> Optional[str]:
        response = self.client.describe_log_streams(
            logGroupName=self.log_group_name,
            logStreamNamePrefix=self.log_stream_name,
        )
        streams = response.get("logStreams", [])
        for stream in streams:
            if stream.get("logStreamName") == self.log_stream_name:
                return stream.get("uploadSequenceToken")
        return None

    def _put_log_events(self, log_events: List[Dict[str, Any]]) -> None:
        kwargs: Dict[str, Any] = {
            "logGroupName": self.log_group_name,
            "logStreamName": self.log_stream_name,
            "logEvents": log_events,
        }
        if self.sequence_token:
            kwargs["sequenceToken"] = self.sequence_token

        try:
            response = self.client.put_log_events(**kwargs)
            self.sequence_token = response.get("nextSequenceToken", self.sequence_token)
        except ClientError as e:
            code = e.response.get("Error", {}).get("Code", "")
            if code == "InvalidSequenceTokenException":
                self.sequence_token = self._get_sequence_token()
                if self.sequence_token:
                    kwargs["sequenceToken"] = self.sequence_token
                    response = self.client.put_log_events(**kwargs)
                    self.sequence_token = response.get("nextSequenceToken", self.sequence_token)
                else:
                    raise
            else:
                raise

    @staticmethod
    def _format_event_message(
        level: str,
        message: str,
        correlation_id: str,
        extra: Optional[Dict[str, Any]] = None,
    ) -> str:
        payload: Dict[str, Any] = {
            "timestamp": int(time.time() * 1000),
            "level": level.upper(),
            "message": message,
            "correlation_id": correlation_id,
        }
        if extra:
            payload["extra"] = extra
        return json.dumps(payload, separators=(",", ":"), ensure_ascii=False)

    def emit(
        self,
        level: str,
        message: str,
        correlation_id: str,
        extra: Optional[Dict[str, Any]] = None,
        timestamp_ms: Optional[int] = None,
    ) -> Dict[str, Any]:
        event = {
            "timestamp": timestamp_ms if timestamp_ms is not None else int(time.time() * 1000),
            "message": self._format_event_message(level, message, correlation_id, extra),
        }
        self._put_log_events([event])
        return event

    def emit_batch(
        self,
        events: Iterable[Dict[str, Any]],
        correlation_id: str,
    ) -> List[Dict[str, Any]]:
        log_events: List[Dict[str, Any]] = []
        normalized: List[Dict[str, Any]] = []

        for event in events:
            level = str(event.get("level", "INFO"))
            message = str(event.get("message", ""))
            extra = event.get("extra")
            timestamp_ms = event.get("timestamp_ms")
            log_event = {
                "timestamp": int(timestamp_ms) if timestamp_ms is not None else int(time.time() * 1000),
                "message": self._format_event_message(level, message, correlation_id, extra if isinstance(extra, dict) else None),
            }
            log_events.append(log_event)
            normalized.append(log_event)

        if log_events:
            log_events.sort(key=lambda e: e["timestamp"])
            self._put_log_events(log_events)

        return normalized


def generate_correlation_id() -> str:
    return uuid.uuid4().hex


def write_application_log_events(
    log_group_name: str,
    log_stream_name: Optional[str] = None,
    correlation_id: Optional[str] = None,
    events: Optional[Iterable[Dict[str, Any]]] = None,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Convenience function to write one or more app log events that share a correlation identifier.
    """
    cid = correlation_id or generate_correlation_id()
    logger = CloudWatchCorrelationLogger(
        log_group_name=log_group_name,
        log_stream_name=log_stream_name,
        region_name=region_name,
    )

    written: List[Dict[str, Any]] = []
    if events is None:
        written.append(logger.emit("INFO", "application event", cid))
    else:
        written.extend(logger.emit_batch(events, cid))

    return {
        "correlation_id": cid,
        "log_group_name": log_group_name,
        "log_stream_name": logger.log_stream_name,
        "events_written": written,
    }
